// Edit here: search terms, places and how far back to look
const config = {
  terms: ['python', 'desenvolvedor júnior', 'automação', 'inteligência artificial'],
  remote: true,          // include 100% remote jobs from anywhere
  cities: ['Mossoró'],   // on-site or hybrid only in these cities
  maxAgeHours: 24,
  limit: 100,            // Gupy results per search
};

const places = [
  ...(config.remote ? ['workplaceType=remote'] : []),
  ...config.cities.map(c => 'city=' + encodeURIComponent(c)),
];

return config.terms.flatMap(term => places.map(place => ({
  json: {
    config,
    url: `https://portal.gupy.io/api/job-search/jobs?jobName=${encodeURIComponent(term)}&limit=${config.limit}&${place}`,
  },
})));

// Merge every search, drop repeats, keep only allowed places and recent posts
const config = $('Definir buscas').first().json.config;
const norm = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const cities = config.cities.map(norm);
const cutoff = Date.now() - config.maxAgeHours * 3600 * 1000;

const seen = new Set();
const jobs = [];
for (const item of $input.all()) {
  for (const v of item.json.data || []) {
    const id = String(v.id);
    if (seen.has(id)) continue;
    seen.add(id);
    const remote = v.workplaceType === 'remote';
    const placeOk = remote ? config.remote : cities.includes(norm(v.city));
    if (!placeOk || !(Date.parse(v.publishedDate) >= cutoff)) continue;
    jobs.push({
      id,
      title: v.name,
      company: v.careerPageName || '',
      place: remote ? 'Remoto' : `${v.city}/${v.state}`,
      url: v.jobUrl,
      text: `Empresa: ${v.careerPageName || ''} ${v.name} ${v.description || ''}`.slice(0, 50000),
    });
  }
}

if (!jobs.length) return []; // nothing new today: stop here, no e-mail

// The detector API takes up to 500 ads per call; a day of these searches stays far below that
const batch = jobs.slice(0, 500);
return [{
  json: {
    jobs: batch,
    payload: { jobs: batch.map(j => ({ id: j.id, title: j.title, text: j.text })) },
  },
}];

// Build the HTML e-mail: jobs worth reading first, then what the scam detector dropped
const jobs = $('Filtrar vagas novas').first().json.jobs;
const byId = Object.fromEntries(jobs.map(j => [j.id, j]));
// the detector answers with a list; n8n turns each element into an item
const results = $input.all().flatMap(i => (Array.isArray(i.json) ? i.json : [i.json]));

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const link = u => (/^https:\/\//.test(u || '') ? esc(u) : '#'); // job data is external input

const keep = results.filter(r => r.verdict === 'ok' || r.verdict === 'ALERTA');
const dropped = results.filter(r => !keep.includes(r));

const kept = keep.map(r => {
  const j = byId[r.id];
  const warn = r.verdict === 'ALERTA' ? ` <b>Atenção:</b> ${esc(r.signals.map(s => s.meaning).join('; '))}` : '';
  return `<li><a href="${link(j.url)}">${esc(j.title)}</a> · ${esc(j.company)} · ${esc(j.place)}${warn}</li>`;
});
const gone = dropped.map(r => {
  const j = byId[r.id];
  return `<li>${esc(j.title)} · ${esc(j.company)}: ${esc(r.verdict)} (${esc(r.signals.map(s => s.code).join(', '))})</li>`;
});

const html = [
  `<h2>${keep.length} vaga(s) nova(s)</h2>`,
  keep.length ? `<ul>${kept.join('')}</ul>` : '<p>Nenhuma vaga passou pelo detector hoje.</p>',
  dropped.length ? `<h3>${dropped.length} descartada(s) pelo detector de golpe</h3><ul>${gone.join('')}</ul>` : '',
].join('\n');

return [{ json: { subject: `Alerta de vagas: ${keep.length} nova(s)`, html } }];
